# ==============================================================================
# --- 3. Flatten nested gene program list ---
# ==============================================================================

flatten_gene_programs <- function(program_list) {
  
  flattened <- list()
  
  for (program_name in names(program_list)) {
    for (submodule_name in names(program_list[[program_name]])) {
      
      new_name <- paste(program_name, submodule_name, sep = " - ")
      flattened[[new_name]] <- program_list[[program_name]][[submodule_name]]
    }
  }
  
  return(flattened)
}

spatial_gene_sets <- flatten_gene_programs(spatial_gene_programs)


# ==============================================================================
# --- 4. Helper function for spatial feature plotting ---
# ==============================================================================

filter_genes_present <- function(genes, object) {
  
  genes_present <- genes[genes %in% rownames(object)]
  genes_missing <- setdiff(genes, genes_present)
  
  if (length(genes_missing) > 0) {
    warning(
      "The following genes were not found and will be skipped: ",
      paste(genes_missing, collapse = ", ")
    )
  }
  
  return(genes_present)
}


make_spatial_feature_plots <- function(
    object,
    genes,
    program_name,
    slot_use = "data",
    image_alpha = 0,
    point_size_factor = 4,
    crop = FALSE,
    ncol = 2,
    palette = c("scico_oslo", "viridis_magma", "viridis_viridis", "viridis_mako",
                "viridis_rocket", "white_purple", "white_red", "blue"),
    lower_limit = 0,
    upper_limit = NA_real_
) {
  
  palette <- match.arg(palette)
  
  genes_present <- filter_genes_present(
    genes = genes,
    object = object
  )
  
  if (length(genes_present) == 0) {
    warning("No genes available for program: ", program_name)
    return(NULL)
  }
  
  plot_list <- list()
  
  for (gene in genes_present) {
    
    p <- SpatialFeaturePlot(
      object = object,
      features = gene,
      image.alpha = image_alpha,
      pt.size.factor = point_size_factor,
      slot = slot_use,
      crop = crop,
      ncol = ncol
    )
    
    if (palette == "scico_oslo") {
      p <- p &
        scale_fill_scico(
          palette = "oslo",
          direction = -1,
          limits = c(lower_limit, upper_limit),
          oob = scales::squish
        )
    }
    
    if (palette == "viridis_magma") {
      p <- p &
        scale_fill_viridis(
          option = "magma",
          limits = c(lower_limit, upper_limit),
          oob = scales::squish
        )
    }
    
    if (palette == "viridis_viridis") {
      p <- p &
        scale_fill_viridis(
          option = "viridis",
          limits = c(lower_limit, upper_limit),
          oob = scales::squish
        )
    }
    
    if (palette == "viridis_mako") {
      p <- p &
        scale_fill_viridis(
          option = "mako",
          limits = c(lower_limit, upper_limit),
          oob = scales::squish
        )
    }
    
    if (palette == "viridis_rocket") {
      p <- p &
        scale_fill_viridis(
          option = "rocket",
          limits = c(lower_limit, upper_limit),
          oob = scales::squish
        )
    }
    
    if (palette == "white_purple") {
      color_wp <- colorRampPalette(c("white", "purple"))(100)
      
      p <- p &
        scale_fill_gradientn(
          colors = color_wp,
          limits = c(lower_limit, upper_limit),
          oob = scales::squish
        )
    }
    
    if (palette == "white_red") {
      color_wr <- colorRampPalette(c("white", "red"))(100)
      
      p <- p &
        scale_fill_gradientn(
          colors = color_wr,
          limits = c(lower_limit, upper_limit),
          oob = scales::squish
        )
    }
    
    if (palette == "blue") {
      p <- p &
        scale_fill_distiller(
          palette = "Blues",
          direction = 1,
          limits = c(lower_limit, upper_limit),
          oob = scales::squish
        )
    }
    
    p <- p &
      ggtitle(paste0(program_name, " - ", gene))
    
    plot_list[[gene]] <- p
  }
  
  return(plot_list)
}


# ==============================================================================
# --- 5. Select gene programs for spatial mapping ---
# ==============================================================================

# Option 1:
#   Plot only selected programs.
selected_programs <- c(
  "Chemokines - Chemokines"
)

# Option 2:
#   Plot all programs.
# selected_programs <- names(spatial_gene_sets)

selected_programs <- intersect(
  selected_programs,
  names(spatial_gene_sets)
)

if (length(selected_programs) == 0) {
  stop("No selected programs were found in spatial_gene_sets.")
}


# ==============================================================================
# --- 6. Generate spatial feature plots ---
# ==============================================================================

spatial_feature_plots <- list()

for (program_name in selected_programs) {
  
  message("Generating spatial feature plots for: ", program_name)
  
  spatial_feature_plots[[program_name]] <- make_spatial_feature_plots(
    object = seu_int_rpca,
    genes = spatial_gene_sets[[program_name]],
    program_name = program_name,
    slot_use = "data",
    image_alpha = 0,
    point_size_factor = 4,
    crop = FALSE,
    ncol = 2,
    palette = "scico_oslo",
    lower_limit = 0,
    upper_limit = NA_real_
  )
}


# Example:
# Print all chemokine spatial feature plots.
if ("Chemokines - Chemokines" %in% names(spatial_feature_plots)) {
  
  for (gene in names(spatial_feature_plots[["Chemokines - Chemokines"]])) {
    print(spatial_feature_plots[["Chemokines - Chemokines"]][[gene]])
  }
}


